package com.otgflasher.pro;import android.app.Activity;import android.os.Bundle;import android.widget.*;import java.io.*;public class KgActivity extends Activity{TextView txtDetail,log;ProgressBar bar;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_kg);txtDetail=findViewById(R.id.txt_detail);log=findViewById(R.id.log_view);bar=findViewById(R.id.progress_bar);findViewById(R.id.btn_back).setOnClickListener(v->finish());findViewById(R.id.btn_disable_kgclient_0).setOnClickListener(v->run("adb shell pm disable-user --user 0 com.samsung.android.kgclient"));
findViewById(R.id.btn_disable_mdm_1).setOnClickListener(v->run("adb shell pm disable-user --user 0 com.samsung.android.mdm"));
findViewById(R.id.btn_disable_knox_2).setOnClickListener(v->run("adb shell pm disable-user --user 0 com.samsung.knox.kpecore"));
findViewById(R.id.btn_bypass_kg_state_0_3).setOnClickListener(v->run("adb shell settings put secure kg_state 0"));
}void run(String c){bar.setProgress(5);log.append("\n> "+c+"\n");new Thread(()->{try{Process p=Runtime.getRuntime().exec(new String[]{"sh","-c",c+" 2>&1"});BufferedReader r=new BufferedReader(new InputStreamReader(p.getInputStream()));String l;int pr=5;while((l=r.readLine())!=null){pr+=2;if(pr>95)pr=95;String ll=l;int pp=pr;runOnUiThread(()->{bar.setProgress(pp);txtDetail.setText(pp+"% "+ll);log.append(ll+"\n");});}p.waitFor();runOnUiThread(()->bar.setProgress(100));}catch(Exception e){runOnUiThread(()->log.append("ERR "+e.getMessage()+"\n"));}}).start();}}